/* solhint-disable one-contract-per-file */
pragma solidity >=0.7.0 <0.9.0;

abstract contract ISignatureValidatorConstants {
    // bytes4(keccak256("isValidSignature(bytes32,bytes)")
    bytes4 internal constant EIP1271_MAGIC_VALUE = 0x1626ba7e;
}

abstract contract ISignatureValidator is ISignatureValidatorConstants {
    /**
     * @notice EIP1271 method to validate a signature.
     * @param _hash Hash of the data signed on the behalf of address(this).
     * @param _signature Signature byte array associated with _data.
     *
     * MUST return the bytes4 magic value 0x1626ba7e when function passes.
     * MUST NOT modify state (using STATICCALL for solc < 0.5, view modifier for solc > 0.5)
     * MUST allow external calls
     */
    function isValidSignature(bytes32 _hash, bytes memory _signature) external view virtual returns (bytes4);
}
","keccak256":"0x123b8d95c7beca245ac8d5f11530b7765768ab864a782453bf52f6da9ecfd6a4","license":"LGPL-3.0-only"},"contracts/interfaces/IStorageAccessible.sol":{"content":"// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity >=0.7.0 <0.9.0;

/**
 * @title Storage Accessible Interface
 * @author @safe-global/safe-protocol
 */
interface IStorageAccessible {
    /**
     * @notice Reads `length` bytes of storage in the current contract
     * @param offset The offset in the current contract's storage in words to start reading from.
     * @param length The number of words (32 bytes) of data to read.
     * @return The bytes that were read.
     */
    function getStorageAt(uint256 offset, uint256 length) external view returns (bytes memory);

    /**
